def leadform(title='',btn='SUBMIT',fields=None):
  fields=fields or [('Name','text',False),('Phone*','tel',True),('Email*','email',True)]
  f=''.join(f'<div><label>{n}</label><input type="{t}" {"required" if r else ""} placeholder="{n}"></div>' for n,t,r in fields)
  return f'''<form class="lead" data-placeholder>{f'<h3 class="full">{title}</h3>' if title else ''}{f}<div class="full"><label>Message</label><textarea placeholder="Message"></textarea></div>{consent()}<div class="full"><button class="btn" type="submit">{btn}</button></div></form>'''
def page(path,title,body,desc=''):
  depth=path.count('/');P='../'*depth
