def lfield(f,k):
  L=open(C/f).read().split('\n')
  for i,l in enumerate(L):
    if l.strip()==k: return L[i+1].strip()
  return ''
LIST=[]
for src,slug in [('2983-juniper-hills-blvd--102.txt','2983-juniper-hills-blvd-102'),('5298-aurora-beam-ave.txt','5298-aurora-beam-ave'),('5855-valley-dr--2044.txt','5855-valley-dr-2044')]:
  L=[l for l in open(C/src).read().split('\n')]
  i=L.index('Listed by Real Broker LLC');desc=L[i-1]
  d=dict(slug=slug,type=L[0],price=L[1].replace('$ ','$'),addr=L[2],city=L[4],beds=L[6],baths=L[8],sqft=L[10],desc=desc)
  for k in ['Sub Type','Listing Status','Purchase Type','Square Footage','Subdivision','MLS Listing ID','Style','Year Built','HOA Y/N','County','Community','Zoning','Direction','Price per Sqft','Lot Size']:
    v=lfield(src,k)
    if v and v not in ('LOCATION','BUILDING','KEY DETAILS'): d[k]=v
  LIST.append(d)
