def items(lines):
  out='';blk=[]
  def flush():
    nonlocal out,blk
    if blk:
      h=E(blk[0]);rest=''.join((f'<br><a href="{x if x.startswith("http") else "https://"+x}" target="_blank" rel="noopener">{E(x)}</a>' if re.match(r'^(https?://|www\.)',x) else f'<br>{E(x)}') for x in blk[1:])
      out+=f'<div class="item"><strong style="font-family:Poppins">{h}</strong>{rest}</div>';blk=[]
  for i,x in enumerate(lines):
    is_head=not re.match(r'^(https?://|www\.|Office|Phone|PHONE|Customer|\d|\(|800-|866)',x) and not re.search(r'NV \d{5}$|Dr\.|Blvd\.|Ave\.|Rd\.$',x)
    if is_head: flush()
    blk.append(x)
  flush();return out
